<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Ubuntu Desktop</title>
<style>
  * { box-sizing: border-box; }
  html, body {
    margin: 0; padding: 0; height: 100%; width: 100%;
    overflow: hidden;
    font-family: Ubuntu, "Segoe UI", Cantarell, "Helvetica Neue", Arial, sans-serif;
    color: #f2f1f0;
    -webkit-font-smoothing: antialiased;
  }

  /* ---------- desktop ---------- */
  #desktop {
    position: fixed;
    inset: 0;
    width: 100vw; height: 100vh;
    background:
      radial-gradient(1200px 700px at 18% 12%, #6a2b3f 0%, rgba(106,43,63,0) 60%),
      radial-gradient(900px 600px at 82% 88%, #7a3a1e 0%, rgba(122,58,30,0) 62%),
      linear-gradient(160deg, #2c001e 0%, #1f0b18 45%, #12090f 100%);
    overflow: hidden;
    user-select: none;
  }
  #desktop::after {
    content: "";
    position: absolute; inset: 0;
    background-image:
      linear-gradient(rgba(255,255,255,.018) 1px, transparent 1px),
      linear-gradient(90deg, rgba(255,255,255,.018) 1px, transparent 1px);
    background-size: 44px 44px;
    pointer-events: none;
  }

  /* ---------- top bar ---------- */
  #topbar {
    position: absolute; top: 0; left: 0; right: 0; height: 28px;
    background: #1b1616;
    border-bottom: 1px solid #000;
    display: flex; align-items: center; justify-content: space-between;
    padding: 0 12px;
    font-size: 12.5px; color: #d8d3d0;
    z-index: 9000;
  }
  #topbar .tb-left { display: flex; gap: 14px; align-items: center; }
  #topbar .tb-right { display: flex; gap: 12px; align-items: center; }
  .tb-dot { width: 8px; height: 8px; border-radius: 50%; background: #e95420; display: inline-block; }

  /* ---------- taskbar / dock ---------- */
  #taskbar {
    position: absolute; top: 28px; left: 0; bottom: 0; width: 68px;
    background: rgba(20,14,18,.86);
    border-right: 1px solid rgba(255,255,255,.08);
    backdrop-filter: blur(6px);
    display: flex; flex-direction: column; align-items: center;
    gap: 10px; padding: 12px 0;
    z-index: 8000;
  }
  .launcher {
    width: 48px; height: 48px;
    border: 1px solid rgba(255,255,255,.10);
    border-radius: 12px;
    background: linear-gradient(180deg, #4a3038, #33202a);
    color: #fff; font-size: 22px; line-height: 1;
    display: flex; align-items: center; justify-content: center;
    cursor: pointer; position: relative;
    transition: transform .12s ease, box-shadow .12s ease, background .12s ease;
  }
  .launcher:hover { transform: translateY(-2px); background: linear-gradient(180deg, #5d3a45, #3d2733); }
  .launcher:active { transform: translateY(0); }
  .launcher.running::before {
    content: ""; position: absolute; left: -7px; top: 50%; transform: translateY(-50%);
    width: 3px; height: 22px; border-radius: 2px; background: #e95420;
  }
  .launcher .tip {
    position: absolute; left: 58px; top: 50%; transform: translateY(-50%);
    background: #000; color: #fff; font-size: 12px; padding: 4px 8px;
    border-radius: 5px; white-space: nowrap; opacity: 0; pointer-events: none;
    transition: opacity .12s ease; z-index: 20;
  }
  .launcher:hover .tip { opacity: .92; }
  #dock-spacer { flex: 1; }
  .dock-trash {
    width: 44px; height: 44px; border-radius: 10px;
    display: flex; align-items: center; justify-content: center;
    font-size: 19px; opacity: .55;
    border: 1px dashed rgba(255,255,255,.18);
  }

  /* ---------- windows ---------- */
  .window {
    position: absolute;
    min-width: 360px; min-height: 240px;
    width: 640px; height: 420px;
    background: #2b2626;
    border: 1px solid rgba(0,0,0,.75);
    border-radius: 10px;
    box-shadow: 0 22px 48px rgba(0,0,0,.62), 0 0 0 1px rgba(255,255,255,.05) inset;
    display: flex; flex-direction: column;
    overflow: hidden;
    z-index: 100;
  }
  .window[hidden] { display: none; }
  .titlebar {
    height: 38px; flex: 0 0 38px;
    background: linear-gradient(180deg, #3b3436, #2f2a2b);
    border-bottom: 1px solid #1a1616;
    display: flex; align-items: center; padding: 0 8px 0 12px;
    cursor: move;
  }
  .titlebar .title {
    flex: 1; font-size: 13.5px; font-weight: 600; color: #efeae8;
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  }
  .win-btns { display: flex; gap: 6px; align-items: center; }
  .win-btn {
    width: 24px; height: 24px; border-radius: 50%;
    border: 1px solid rgba(0,0,0,.4);
    background: #4b4243; color: #ddd;
    font-size: 13px; line-height: 1;
    display: flex; align-items: center; justify-content: center;
    cursor: pointer; padding: 0;
  }
  .win-btn:hover { background: #5c5152; }
  .win-close:hover { background: #e95420; color: #fff; border-color: #b93f14; }
  .win-body { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }

  /* ---------- files app ---------- */
  #files-window { left: 140px; top: 80px; width: 720px; height: 460px; }
  .files-toolbar {
    display: flex; align-items: center; gap: 8px;
    padding: 8px 10px; background: #332d2e;
    border-bottom: 1px solid #1c1818;
  }
  .tool-btn {
    background: #443c3d; color: #eee; border: 1px solid #262020;
    border-radius: 6px; padding: 5px 11px; font-size: 13px; cursor: pointer;
  }
  .tool-btn:hover { background: #544a4b; }
  .tool-btn:disabled { opacity: .4; cursor: default; }
  #files-path {
    flex: 1; background: #221d1e; border: 1px solid #171313;
    border-radius: 6px; padding: 6px 10px;
    font-family: "Ubuntu Mono", Consolas, monospace; font-size: 13px; color: #f8b58a;
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  }
  .files-main { flex: 1 1 auto; min-height: 0; display: flex; }
  .files-side {
    width: 168px; flex: 0 0 168px; background: #2a2425;
    border-right: 1px solid #1b1717; padding: 8px 6px; overflow: auto;
  }
  .side-head { font-size: 11px; text-transform: uppercase; letter-spacing: .08em; color: #9a8f8c; padding: 6px 8px; }
  .side-item {
    padding: 6px 9px; border-radius: 6px; font-size: 13px; color: #ddd6d3; cursor: pointer;
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  }
  .side-item:hover { background: #3b3334; }
  #files-list {
    flex: 1 1 auto; min-height: 0; overflow: auto; padding: 10px;
    display: flex; flex-wrap: wrap; align-content: flex-start; gap: 6px;
  }
  .fs-item {
    width: 108px; padding: 10px 6px;
    display: flex; flex-direction: column; align-items: center; gap: 6px;
    border-radius: 8px; cursor: default; text-align: center;
    font-size: 12.5px; color: #ece7e5; border: 1px solid transparent;
  }
  .fs-item:hover { background: #3a3233; }
  .fs-item.selected { background: #5a2f22; border-color: #e95420; }
  .fs-item .ico { font-size: 26px; line-height: 1; }
  .fs-item .nm { word-break: break-word; line-height: 1.25; }
  .files-status {
    flex: 0 0 26px; height: 26px; background: #262121; border-top: 1px solid #1a1616;
    display: flex; align-items: center; padding: 0 10px; font-size: 11.5px; color: #a99f9c;
  }
  .empty-note { color: #8d8280; font-size: 13px; padding: 14px; font-style: italic; }

  /* ---------- notepad app ---------- */
  #notepad-window { left: 420px; top: 150px; width: 620px; height: 440px; }
  #tabs {
    flex: 0 0 auto; display: flex; align-items: stretch; gap: 2px;
    background: #262121; border-bottom: 1px solid #171313;
    padding: 6px 6px 0 6px; overflow-x: auto;
  }
  .tab {
    display: flex; align-items: center; gap: 6px;
    max-width: 190px; padding: 7px 8px 7px 12px;
    background: #342e2f; color: #cfc7c4;
    border: 1px solid #1d1919; border-bottom: none;
    border-radius: 7px 7px 0 0; font-size: 12.5px; cursor: pointer;
    white-space: nowrap; flex: 0 0 auto;
  }
  .tab:hover { background: #3e3637; }
  .tab.active { background: #221d1e; color: #fff; border-bottom: 1px solid #221d1e; }
  .tab .tab-name { overflow: hidden; text-overflow: ellipsis; max-width: 130px; }
  .tab .tab-x {
    width: 17px; height: 17px; border-radius: 50%; border: none;
    background: transparent; color: #b6acaa; font-size: 12px; line-height: 1;
    display: flex; align-items: center; justify-content: center; cursor: pointer; padding: 0;
  }
  .tab .tab-x:hover { background: #e95420; color: #fff; }
  #new-tab {
    flex: 0 0 auto; align-self: center; margin-left: 4px;
    width: 26px; height: 26px; border-radius: 6px;
    background: #3d3536; color: #eee; border: 1px solid #221d1e;
    font-size: 16px; line-height: 1; cursor: pointer; padding: 0;
  }
  #new-tab:hover { background: #e95420; border-color: #b93f14; }
  #editor {
    flex: 1 1 auto; min-height: 0; width: 100%;
    background: #221d1e; color: #f1ece9;
    border: none; outline: none; resize: none;
    padding: 14px 16px;
    font-family: "Ubuntu Mono", Consolas, monospace;
    font-size: 14px; line-height: 1.55;
  }
  .np-status {
    flex: 0 0 26px; height: 26px; background: #262121; border-top: 1px solid #171313;
    display: flex; align-items: center; justify-content: space-between;
    padding: 0 10px; font-size: 11.5px; color: #a99f9c;
  }
</style>
