<script>
(function () {
  "use strict";

  /* ============ generic window plumbing ============ */
  var zTop = 100;
  function focusWin(win) { zTop += 1; win.style.zIndex = String(zTop); }

  function openWin(win, launcher) {
    win.hidden = false;
    // guarantee a usable size even if something upstream squashed it
    if (win.offsetWidth < 360) win.style.width = "640px";
    if (win.offsetHeight < 240) win.style.height = "420px";
    focusWin(win);
    if (launcher) launcher.classList.add("running");
  }
  function closeWin(win, launcher) {
    win.hidden = true;
    win.style.display = "none";
    if (launcher) launcher.classList.remove("running");
  }
  function showWin(win) { win.style.display = ""; win.hidden = false; }

  function wireWindow(win, launcher) {
    win.addEventListener("mousedown", function () { focusWin(win); });

    var closeBtn = win.querySelector(".win-close");
    closeBtn.addEventListener("click", function (e) {
      e.stopPropagation();
      closeWin(win, launcher);
    });

    var minBtn = win.querySelector(".win-min");
    if (minBtn) minBtn.addEventListener("click", function (e) {
      e.stopPropagation();
      closeWin(win, launcher);
    });

    // dragging by titlebar
    var bar = win.querySelector(".titlebar");
    var drag = null;
    bar.addEventListener("mousedown", function (e) {
      if (e.target.closest(".win-btn")) return;
      focusWin(win);
      drag = { dx: e.clientX - win.offsetLeft, dy: e.clientY - win.offsetTop };
      e.preventDefault();
    });
    document.addEventListener("mousemove", function (e) {
      if (!drag) return;
      var x = e.clientX - drag.dx, y = e.clientY - drag.dy;
      var maxX = window.innerWidth - 60, maxY = window.innerHeight - 40;
      win.style.left = Math.max(-win.offsetWidth + 120, Math.min(x, maxX)) + "px";
      win.style.top  = Math.max(28, Math.min(y, maxY)) + "px";
    });
    document.addEventListener("mouseup", function () { drag = null; });
  }

  var filesWin   = document.getElementById("files-window");
  var notepadWin = document.getElementById("notepad-window");
  var btnFiles   = document.getElementById("open-files");
  var btnNotepad = document.getElementById("open-notepad");

  wireWindow(filesWin, btnFiles);
  wireWindow(notepadWin, btnNotepad);

  btnFiles.addEventListener("click", function () {
    showWin(filesWin);
    openWin(filesWin, btnFiles);
    render();
  });
  btnNotepad.addEventListener("click", function () {
    showWin(notepadWin);
    openWin(notepadWin, btnNotepad);
    loadNotes();
    renderTabs();
  });

  /* ============ clock ============ */
  var clock = document.getElementById("tb-clock");
  function tick() {
    var d = new Date();
    var days = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
    var h = String(d.getHours()).padStart(2, "0");
    var m = String(d.getMinutes()).padStart(2, "0");
    clock.textContent = days[d.getDay()] + " " + h + ":" + m;
  }
  tick(); setInterval(tick, 10000);

  /* ================= FILES APP ================= */
  // Static fake filesystem. dir => { name: null (file) | {…} (dir) }
  function f(size) { return { type: "file", size: size }; }

  var FS = {
    "bin": {
      "bash": f("1.2M"), "cat": f("35K"), "ls": f("142K"), "grep": f("218K"),
      "nano": f("267K"), "python3": f("5.9M"), "sh": f("128K")
    },
    "boot": { "grub": { "grub.cfg": f("8.4K") }, "vmlinuz-6.8.0-41-generic": f("14M") },
    "dev": { "null": f("0"), "random": f("0"), "sda1": f("0"), "tty0": f("0") },
    "etc": {
      "apt": { "sources.list": f("2.9K"), "trusted.gpg": f("12K") },
      "systemd": { "system.conf": f("1.8K"), "user.conf": f("1.1K") },
      "network": { "interfaces": f("412B") },
      "fstab": f("704B"), "hostname": f("11B"), "hosts": f("232B"),
      "os-release": f("386B"), "passwd": f("2.7K"), "shadow": f("1.4K")
    },
    "home": {
      "user": {
        "Documents": {
          "notes": { "todo.md": f("1.1K"), "ideas.md": f("640B") },
          "report.odt": f("48K"), "budget.ods": f("22K"), "resume.pdf": f("112K")
        },
        "Downloads": {
          "ubuntu-24.04.1-desktop-amd64.iso": f("5.7G"),
          "archive.tar.gz": f("18M"), "installer.deb": f("42M")
        },
        "Pictures": {
          "Screenshots": { "screenshot-2026-07-25.png": f("880K") },
          "wallpaper.png": f("2.4M"), "cat.jpg": f("640K")
        },
        "Music": { "track01.flac": f("31M") },
        "Videos": { "clip.mp4": f("88M") },
        "Desktop": { "shortcut.desktop": f("212B") },
        ".bashrc": f("3.7K"), ".profile": f("807B"), "hello.txt": f("54B")
      },
      "guest": { "README": f("96B") }
    },
    "lib": { "modules": { "6.8.0-41-generic": { "kernel": {} } }, "systemd": { "systemd": f("1.7M") } },
    "media": { "cdrom": {} },
    "mnt": { "backup": {} },
    "opt": { "google": { "chrome": { "chrome": f("210M") } } },
    "proc": { "cpuinfo": f("0"), "meminfo": f("0"), "uptime": f("0") },
    "root": { ".bashrc": f("3.1K") },
    "run": { "lock": {}, "user": { "1000": {} } },
    "sbin": { "fsck": f("88K"), "ifconfig": f("74K"), "reboot": f("28K") },
    "srv": { "www": { "index.html": f("1.9K") } },
    "sys": { "class": {}, "devices": {} },
    "tmp": { "session.lock": f("0"), "cache-98a1.tmp": f("1.2M") },
    "usr": {
      "bin": { "gcc": f("1.1M"), "git": f("3.2M"), "node": f("78M"), "vim": f("3.6M") },
      "lib": { "x86_64-linux-gnu": { "libc.so.6": f("2.0M") } },
      "local": { "bin": { "myscript.sh": f("512B") }, "share": {} },
      "share": { "applications": { "firefox.desktop": f("8.1K") }, "doc": {}, "icons": {} }
    },
    "var": {
      "cache": { "apt": { "archives": {} } },
      "lib": { "dpkg": { "status": f("2.8M") } },
      "log": { "syslog": f("4.2M"), "auth.log": f("612K"), "dmesg": f("128K"), "apt": { "history.log": f("94K") } },
      "tmp": {},
      "www": { "html": { "index.html": f("612B") } }
    }
  };

  function isDir(node) { return node && typeof node === "object" && node.type !== "file"; }

  function resolve(path) {
    if (path === "/" || path === "") return FS;
    var parts = path.split("/").filter(Boolean);
    var node = FS;
    for (var i = 0; i < parts.length; i++) {
      if (!isDir(node) || !Object.prototype.hasOwnProperty.call(node, parts[i])) return null;
      node = node[parts[i]];
    }
    return node;
  }

  var pathEl   = document.getElementById("files-path");
  var listEl   = document.getElementById("files-list");
  var statusEl = document.getElementById("files-status");
  var upBtn    = document.getElementById("files-up");
  var homeBtn  = document.getElementById("files-home");
  var cwd = "/";

  function join(base, name) { return base === "/" ? "/" + name : base + "/" + name; }
  function parentOf(p) {
    if (p === "/" ) return "/";
    var parts = p.split("/").filter(Boolean);
    parts.pop();
    return parts.length ? "/" + parts.join("/") : "/";
  }

  function iconFor(name, dir) {
    if (dir) return "📁";
    var n = name.toLowerCase();
    if (/\.(png|jpg|jpeg|gif|svg|webp)$/.test(n)) return "🖼";
    if (/\.(mp4|mkv|avi|webm)$/.test(n)) return "🎬";
    if (/\.(mp3|flac|ogg|wav)$/.test(n)) return "🎵";
    if (/\.(pdf|odt|doc|docx|md|txt|log|cfg|conf|list)$/.test(n)) return "📄";
    if (/\.(gz|zip|tar|xz|deb|iso)$/.test(n)) return "📦";
    if (/\.(sh|py|js)$/.test(n)) return "⚙";
    return "📃";
  }

  function navigate(path) {
    var node = resolve(path);
    if (!isDir(node)) return;
    cwd = path;
    render();
  }

  function render() {
    var node = resolve(cwd);
    if (!isDir(node)) { cwd = "/"; node = FS; }
    pathEl.textContent = cwd;
    pathEl.title = cwd;
    listEl.innerHTML = "";

    var names = Object.keys(node).sort(function (a, b) {
      var da = isDir(node[a]) ? 0 : 1, db = isDir(node[b]) ? 0 : 1;
      if (da !== db) return da - db;
      return a.toLowerCase().localeCompare(b.toLowerCase());
    });

    if (!names.length) {
      var empty = document.createElement("div");
      empty.className = "empty-note";
      empty.textContent = "This folder is empty.";
      listEl.appendChild(empty);
    }

    var dirs = 0, files = 0;
    names.forEach(function (name) {
      var child = node[name];
      var dir = isDir(child);
      dir ? dirs++ : files++;

      var el = document.createElement("div");
      el.className = "fs-item";
      el.setAttribute("data-name", name);
      el.setAttribute("data-type", dir ? "dir" : "file");
      el.title = join(cwd, name) + (dir ? "" : "  (" + child.size + ")");
      el.tabIndex = 0;

      var ico = document.createElement("div");
      ico.className = "ico";
      ico.textContent = iconFor(name, dir);
      var nm = document.createElement("div");
      nm.className = "nm";
      nm.textContent = name;
      el.appendChild(ico);
      el.appendChild(nm);

      el.addEventListener("click", function () {
        Array.prototype.forEach.call(listEl.querySelectorAll(".fs-item.selected"),
          function (s) { s.classList.remove("selected"); });
        el.classList.add("selected");
        statusEl.textContent = name + (dir ? "  —  folder" : "  —  " + child.size);
      });
      el.addEventListener("dblclick", function () {
        if (dir) navigate(join(cwd, name));
        else statusEl.textContent = "No application available to open “" + name + "”";
      });
      el.addEventListener("keydown", function (e) {
        if (e.key === "Enter" && dir) navigate(join(cwd, name));
      });

      listEl.appendChild(el);
    });

    statusEl.textContent = names.length + " item" + (names.length === 1 ? "" : "s") +
      "  (" + dirs + " folder" + (dirs === 1 ? "" : "s") + ", " + files + " file" + (files === 1 ? "" : "s") + ")";
    upBtn.disabled = (cwd === "/");
  }

  upBtn.addEventListener("click", function () { navigate(parentOf(cwd)); });
  homeBtn.addEventListener("click", function () { navigate("/home/user"); });
  Array.prototype.forEach.call(document.querySelectorAll(".side-item"), function (si) {
    si.addEventListener("click", function () { navigate(si.getAttribute("data-go")); });
  });

  render();

  /* ================= NOTEPAD APP ================= */
  var STORE_KEY = "ubuntu-desktop.notepad.v1";
  var tabsEl   = document.getElementById("tabs");
  var newTabEl = document.createElement("button");
  newTabEl.id = "new-tab";
  newTabEl.type = "button";
  newTabEl.title = "New tab";
  newTabEl.textContent = "+";

  var editor  = document.getElementById("editor");
  var npInfo  = document.getElementById("np-info");
  var npSaved = document.getElementById("np-saved");

  var state = { tabs: [], activeId: null, seq: 1 };

  function saveNotes() {
    try { localStorage.setItem(STORE_KEY, JSON.stringify(state)); } catch (e) {}
    npSaved.textContent = "saved to localStorage";
  }

  function loadNotes() {
    var raw = null;
    try { raw = localStorage.getItem(STORE_KEY); } catch (e) {}
    if (raw) {
      try {
        var parsed = JSON.parse(raw);
        if (parsed && Array.isArray(parsed.tabs)) {
          state.tabs = parsed.tabs.filter(function (t) { return t && typeof t.id === "string"; })
            .map(function (t) {
              return { id: t.id, name: String(t.name || "Untitled"), content: String(t.content || "") };
            });
          state.seq = typeof parsed.seq === "number" ? parsed.seq : state.tabs.length + 1;
          state.activeId = parsed.activeId || null;
        }
      } catch (e) {}
    }
    if (!state.tabs.length) {
      state.tabs = [];
      addTab("Untitled 1", "", true);
    }
    if (!state.tabs.some(function (t) { return t.id === state.activeId; })) {
      state.activeId = state.tabs[0].id;
    }
  }

  function addTab(name, content, silent) {
    var id = "t" + state.seq + "-" + state.tabs.length;
    var tab = { id: id, name: name || ("Untitled " + state.seq), content: content || "" };
    state.seq += 1;
    state.tabs.push(tab);
    state.activeId = id;
    if (!silent) { saveNotes(); renderTabs(); editor.focus(); }
    return tab;
  }

  function activeTab() {
    for (var i = 0; i < state.tabs.length; i++) {
      if (state.tabs[i].id === state.activeId) return state.tabs[i];
    }
    return null;
  }

  function closeTab(id) {
    var idx = -1;
    for (var i = 0; i < state.tabs.length; i++) if (state.tabs[i].id === id) idx = i;
    if (idx < 0) return;
    state.tabs.splice(idx, 1);
    if (!state.tabs.length) {
      addTab("Untitled " + state.seq, "", true);
    } else if (state.activeId === id) {
      state.activeId = state.tabs[Math.max(0, idx - 1)].id;
    }
    saveNotes();
    renderTabs();
  }

  function renderTabs() {
    tabsEl.innerHTML = "";
    state.tabs.forEach(function (t) {
      var el = document.createElement("div");
      el.className = "tab" + (t.id === state.activeId ? " active" : "");
      el.setAttribute("data-id", t.id);
      el.title = t.name;

      var nameEl = document.createElement("span");
      nameEl.className = "tab-name";
      nameEl.textContent = t.name;

      var x = document.createElement("button");
      x.className = "tab-x";
      x.type = "button";
      x.title = "Close tab";
      x.textContent = "✕";
      x.addEventListener("click", function (e) { e.stopPropagation(); closeTab(t.id); });

      el.appendChild(nameEl);
      el.appendChild(x);
      el.addEventListener("click", function () {
        if (state.activeId === t.id) return;
        state.activeId = t.id;
        saveNotes();
        renderTabs();
        editor.focus();
      });
      tabsEl.appendChild(el);
    });
    tabsEl.appendChild(newTabEl);

    var t = activeTab();
    editor.value = t ? t.content : "";
    updateInfo();
  }

  function updateInfo() {
    var t = activeTab();
    if (!t) { npInfo.textContent = "—"; return; }
    var chars = t.content.length;
    var lines = t.content.length ? t.content.split("\n").length : 1;
    npInfo.textContent = t.name + "  •  " + lines + " line" + (lines === 1 ? "" : "s") +
      ", " + chars + " char" + (chars === 1 ? "" : "s");
  }

  newTabEl.addEventListener("click", function () {
    addTab("Untitled " + state.seq, "");
  });

  editor.addEventListener("input", function () {
    var t = activeTab();
    if (!t) return;
    t.content = editor.value;
    // first non-empty line (trimmed) becomes the tab label
    var first = (editor.value.split("\n")[0] || "").trim();
    if (first) t.name = first.length > 22 ? first.slice(0, 22) + "…" : first;
    var el = tabsEl.querySelector('.tab[data-id="' + t.id + '"] .tab-name');
    if (el) { el.textContent = t.name; el.parentElement.title = t.name; }
    npSaved.textContent = "unsaved…";
    updateInfo();
    saveNotes();
  });

  editor.addEventListener("keydown", function (e) {
    if (e.key === "Tab") {
      e.preventDefault();
      var s = editor.selectionStart, en = editor.selectionEnd;
      editor.value = editor.value.slice(0, s) + "  " + editor.value.slice(en);
      editor.selectionStart = editor.selectionEnd = s + 2;
      editor.dispatchEvent(new Event("input"));
    }
  });

  window.addEventListener("beforeunload", saveNotes);

  loadNotes();
  renderTabs();
})();
</script>
